def normalize(text: str, prefix: str) -> str:
    if not isinstance(text, str) or not isinstance(prefix, str):
        raise TypeError("text and prefix must be strings")
    if not prefix.strip():
        raise ValueError("prefix must not be empty")
    return prefix.strip().lower() + ":" + text.strip().lower()

if __name__ == "__main__":
    print(normalize("  Drill STOPPED  ", "urgent"))

import json

def validate_ticket(raw: str) -> dict:
    value = json.loads(raw)
    if not isinstance(value, dict):
        raise ValueError("object required")
    if not isinstance(value.get("text"), str) or not value["text"].strip():
        raise ValueError("non-empty text string required")
    return value

print(validate_ticket('{"text":"Drill stopped"}'))

